--## MONITORS, WINDOWS AND WORKSPACES ###

--#############################

-- See https://wiki.hyprland.org/Configuring/Monitors/

-- TODO: separate monitor settings

hl.monitor({
    output   = "$WM_DP1_NAME",
    mode     = "$WM_DP1_RES",
    position = "$WM_DP1_POS",
    scale    = "$WM_DP1_SCALING",
})

hl.monitor({
    output   = "$WM_DP2_NAME",
    mode     = "$WM_DP2_RES",
    position = "$WM_DP2_POS",
    scale    = "$WM_DP2_SCALING",
})

-- unscale XWayland

hl.config({
    xwayland = {
        force_zero_scaling = true,
    },
})

